-- low-level diagnostic build (`pdc --skip-unknown source Nyandoku.pdx`) and
-- `lua test/run.lua` always have a valid catalog to import/require even when
-- no bake has ever been run -- a missing entry here is just a cache miss,
-- never a failure (source/ui/cache.lua falls back to rasterizing).
UiBakeCatalog = {
  schemaRevision = "1",
  scenes = {},
}
return UiBakeCatalog
